    return count

def max_revenue(N, S):
    @lru_cache(None)
    def dp(mask):
        if mask == 0:
            return 0
        max_rev = 0
        subset_sum = 0
        for i in range(N):
            if mask & (1 << i):
                subset_sum += S[i]
        distinct_prime_factors = count_distinct_prime_factors(subset_sum)
